{
  "findings": [
    {
      "check_id": "CKV_GCP_106",
      "title": "Unrestricted HTTP access on port 80",
      "resource": "google_compute_firewall.allow_http_https",
      "severity": "MEDIUM",
      "explanation": "The firewall rule allows unrestricted access to port 80 from any source IP address (0.0.0.0/0), potentially exposing the web server to unauthorized access."
    }
  ],
  "patched_code": "resource "google_compute_firewall" "allow_http_https" {
  name    = "digital-asset-trading-platform-firewall-web"
  network = google_compute_network.digital_asset_trading_vpc.name
  allow {
    protocol = "tcp"
    ports    = ["443", "8080"]
  }
  allow {
    protocol = "tcp"
    ports    = ["80"]
    source_ranges = ["10.0.0.0/8"] # Example restricted source range
  }
  target_tags   = ["web-server"]
}",
  "fix_summary": "Restrict HTTP access on port 80 to a specific source IP range. For demonstration, '10.0.0.0/8' is used; replace with the actual trusted IP range."
}
